const leads = $input.first().json.leads || [];
const hot = leads.filter(l => l.leadTier === 'hot');
const warm = leads.filter(l => l.leadTier === 'warm');
const totalValue = leads.reduce((s, l) => s + (l.roiAnnualValue || 0), 0);
const avgScore = leads.length ? Math.round(leads.reduce((s, l) => s + (l.leadScore || 0), 0) / leads.length) : 0;

return [{ json: { leads, hot, warm, totalValue, avgScore, count: leads.length } }];
